/**
 * Static, read-only reading of the Aisle Rails source (config/routes.rb and controllers) for the API-docs drift check.
 * Nothing here runs Ruby: the files are read as text (`git show <ref>:<path>`) and only literal, statically visible
 * facts are extracted. Anything built at run time (params passed on whole to a model, a key computed from a variable,
 * a `render json:` of a variable, routes generated by a gem) is reported as "needs review" — never guessed.
 */

// ---- Lexing: one pass that blanks string contents and drops comments, keeping line numbers -------------------------

export interface RubyLine {
  /** 1-based line number in the file. */
  n: number;
  /** The line without its comment (string literals kept). */
  code: string;
  /** The line without its comment and with every string literal's contents blanked (for structure). */
  skel: string;
}

/** Split Ruby source into lines with comments removed; `skel` also blanks string contents (keeps the quotes). */
export function lexRuby(src: string): RubyLine[] {
  const out: RubyLine[] = [];
  const lines = src.split('\n');
  let inBlockComment = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    if (inBlockComment) {
      if (/^=end\b/.test(line)) inBlockComment = false;
      out.push({ n: i + 1, code: '', skel: '' });
      continue;
    }
    if (/^=begin\b/.test(line)) {
      inBlockComment = true;
      out.push({ n: i + 1, code: '', skel: '' });
      continue;
    }
    let code = '';
    let skel = '';
    let q: string | null = null;
    let interp = 0;
    for (let j = 0; j < line.length; j++) {
      const c = line[j]!;
      if (q) {
        code += c;
        if (c === '\\') {
          code += line[j + 1] ?? '';
          j++;
          skel += '  ';
          continue;
        }
        if (q === '"' && c === '#' && line[j + 1] === '{') interp++;
        else if (interp && c === '}') interp--;
        else if (c === q && !interp) {
          q = null;
          skel += c;
          continue;
        }
        skel += ' ';
        continue;
      }
      if (c === '#') break;
      if (c === '"' || c === "'") {
        // A quote right after a word character is not a string start in Ruby source we read (e.g. `ain't` in symbols).
        q = c;
        code += c;
        skel += c;
        continue;
      }
      code += c;
      skel += c;
    }
    out.push({ n: i + 1, code: code.trimEnd(), skel: skel.trimEnd() });
  }
  return out;
}

const OPEN_AT_START = /^\s*(def|class|module|if|unless|while|until|case|begin|for)\b/;
const OPEN_AFTER_ASSIGN = /(?:[^=!<>]=|\()\s*(if|unless|case|begin|while|until)\b/;
const DO_BLOCK = /\bdo\s*(\|[^|]*\|)?\s*$/;

/** Net block depth change of one skeleton line (openers minus `end`s). */
export function depthDelta(skel: string): number {
  const s = skel.replace(/:\w+[?!]?/g, ' ').replace(/\.\s*(end|if|do|class|begin)\b/g, '.x');
  let d = 0;
  if (OPEN_AT_START.test(s)) {
    // `def x = expr` (endless method) does not open a block.
    if (!/^\s*def\s+[\w.?!]+(\([^)]*\))?\s*=[^=~]/.test(s)) d++;
  } else if (OPEN_AFTER_ASSIGN.test(s)) d++;
  if (DO_BLOCK.test(s) || /\bdo\s*\|[^|]*\|/.test(s) || /\bdo\b\s*;/.test(s)) d++;
  d -= (s.match(/(^|[\s;])end\b(?![?!:])/g) ?? []).length;
  return d;
}

export interface RubyMethod {
  name: string;
  /** Argument list text (as written). */
  args: string;
  start: number;
  end: number;
  lines: RubyLine[];
  /** After a bare `private` / `protected` line in the class body. */
  private: boolean;
}

/** Every `def` in a file with its body lines (nested blocks resolved by keyword depth). */
export function rubyMethods(src: string): RubyMethod[] {
  const lines = lexRuby(src);
  const out: RubyMethod[] = [];
  let hidden = false;
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*(private|protected)\s*$/.test(lines[i]!.skel)) hidden = true;
    else if (/^\s*public\s*$/.test(lines[i]!.skel)) hidden = false;
    else if (/^\s*class\b/.test(lines[i]!.skel)) hidden = false;
    const m = lines[i]!.skel.match(/^\s*def\s+(self\.)?([\w?!]+)\s*(\(([^)]*)\)|\s+([^=;]*))?/);
    if (!m) continue;
    const name = m[2]!;
    const args = (m[4] ?? m[5] ?? '').trim();
    let depth = 0;
    let j = i;
    for (; j < lines.length; j++) {
      depth += depthDelta(lines[j]!.skel);
      if (depth <= 0) break;
    }
    const body = lines.slice(i, Math.min(j + 1, lines.length));
    out.push({
      name,
      args,
      start: lines[i]!.n,
      end: lines[Math.min(j, lines.length - 1)]!.n,
      lines: body,
      private: hidden,
    });
  }
  return out;
}

// ---- Routes ----------------------------------------------------------------------------------------------------------

export interface Route {
  verb: string;
  /** Full path, e.g. /V1/users/:ref */
  path: string;
  /** Controller path relative to app/controllers without `_controller`, e.g. v1/users */
  controller: string;
  action: string;
  line: number;
  /** A glob route (`*path`) — never used to resolve a documented endpoint. */
  glob?: boolean;
}

export interface RouteTable {
  routes: Route[];
  /** Route-file statements that generate routes at run time (gems, mounts, constraints) — needs review. */
  dynamic: { line: number; text: string }[];
}

const RESOURCE_ACTIONS: [string, string, string][] = [
  ['index', 'GET', ''],
  ['create', 'POST', ''],
  ['new', 'GET', '/new'],
  ['edit', 'GET', '/:id/edit'],
  ['show', 'GET', '/:id'],
  ['update', 'PATCH', '/:id'],
  ['update', 'PUT', '/:id'],
  ['destroy', 'DELETE', '/:id'],
];

const joinPath = (...parts: string[]) =>
  '/' +
  parts
    .join('/')
    .split('/')
    .filter((p) => p)
    .join('/');
const strArg = (text: string, key: string) =>
  text.match(new RegExp(`\\b${key}:\\s*['"]([^'"]*)['"]`))?.[1] ??
  text.match(new RegExp(`:${key}\\s*=>\\s*['"]([^'"]*)['"]`))?.[1];
const symList = (text: string, key: string) => {
  const m =
    text.match(new RegExp(`\\b${key}:\\s*\\[([^\\]]*)\\]`)) ??
    text.match(new RegExp(`\\b${key}:\\s*:(\\w+)`));
  if (!m) return null;
  return m[1]!
    .split(',')
    .map((s) => s.trim().replace(/^:/, '').replace(/['"]/g, ''))
    .filter(Boolean);
};

/** Parse config/routes.rb into a flat route table (declaration order = Rails' match order). */
export function parseRoutes(src: string): RouteTable {
  const lines = lexRuby(src);
  const routes: Route[] = [];
  const dynamic: RouteTable['dynamic'] = [];
  type Frame = { path: string; module: string; depth: number };
  const stack: Frame[] = [{ path: '', module: '', depth: 0 }];
  let depth = 0;
  const top = () => stack[stack.length - 1]!;
  for (const l of lines) {
    const code = l.code.trim();
    if (!code) continue;
    const delta = depthDelta(l.skel);
    const opens = delta > 0;
    const t = top();
    let m: RegExpMatchArray | null;
    if ((m = code.match(/^(get|post|put|patch|delete|match)\s*\(?\s*(['"])(.*?)\2\s*(.*)$/))) {
      const rest = m[4] ?? '';
      const raw = m[3]!;
      const target =
        rest.match(/^,?\s*=>\s*['"]([^'"#]*)#([^'"]*)['"]/) ??
        rest.match(/\bto:\s*['"]([^'"#]*)#([^'"]*)['"]/);
      let controller: string;
      let action: string;
      if (target) {
        controller = target[1]!;
        action = target[2]!;
      } else if (strArg(rest, 'controller') || strArg(rest, 'action')) {
        controller = strArg(rest, 'controller') ?? '';
        action = strArg(rest, 'action') ?? '';
      } else {
        // `get "fields/faiths"` → fields#faiths (Rails' implicit target).
        const segs = raw.replace(/^\//, '').split('/');
        controller = segs.slice(0, -1).join('/');
        action = segs[segs.length - 1] ?? '';
        if (!controller || /[:*]/.test(raw)) {
          dynamic.push({ line: l.n, text: code });
          continue;
        }
      }
      const verbs =
        m[1] === 'match'
          ? (symList(rest, 'via') ?? ['get']).map((v) => v.toUpperCase())
          : [m[1]!.toUpperCase()];
      const full = joinPath(t.path, raw);
      for (const verb of verbs)
        routes.push({
          verb,
          path: full,
          controller: [t.module, controller].filter(Boolean).join('/'),
          action,
          line: l.n,
          ...(raw.includes('*') ? { glob: true } : {}),
        });
      if (opens) stack.push({ ...t, depth: depth + delta });
    } else if ((m = code.match(/^resources?\s+:(\w+)(.*)$/))) {
      const name = m[1]!;
      const rest = m[2] ?? '';
      const only = symList(rest, 'only');
      const except = symList(rest, 'except') ?? [];
      const singular = code.startsWith('resource ');
      if (opens || singular) dynamic.push({ line: l.n, text: code });
      if (!singular)
        for (const [act, verb, suffix] of RESOURCE_ACTIONS) {
          if (only ? !only.includes(act) : except.includes(act)) continue;
          routes.push({
            verb,
            path: joinPath(t.path, name) + suffix,
            controller: [t.module, name].filter(Boolean).join('/'),
            action: act,
            line: l.n,
          });
        }
      if (opens) stack.push({ ...t, depth: depth + delta });
    } else if ((m = code.match(/^root\s*\(?\s*(?:to:\s*|['"])['"]?([^'"#]*)#([^'"]*)['"]/))) {
      routes.push({
        verb: 'GET',
        path: joinPath(t.path),
        controller: [t.module, m[1]!].filter(Boolean).join('/'),
        action: m[2]!,
        line: l.n,
      });
    } else if ((m = code.match(/^namespace\s+:(\w+)/))) {
      stack.push({
        path: joinPath(t.path, m[1]!),
        module: [t.module, m[1]!].filter(Boolean).join('/'),
        depth: depth + delta,
      });
    } else if (/^scope\b/.test(code)) {
      const p = code.match(/^scope\s*\(?\s*['"]([^'"]*)['"]/)?.[1] ?? strArg(code, 'path') ?? '';
      const mod = strArg(code, 'module');
      stack.push({
        path: joinPath(t.path, p),
        module: mod ? [t.module, mod].filter(Boolean).join('/') : t.module,
        depth: depth + delta,
      });
    } else if (opens) {
      // Rails.application.routes.draw / authenticate / constraints / any other block: same prefix.
      if (!/routes\.draw\b|^authenticate\b/.test(code)) dynamic.push({ line: l.n, text: code });
      stack.push({ ...t, depth: depth + delta });
    } else if (/^(devise_for|mount|ActiveAdmin\.routes|draw|concern|use_doorkeeper)\b/.test(code)) {
      dynamic.push({ line: l.n, text: code });
    }
    depth += delta;
    while (stack.length > 1 && depth < top().depth) stack.pop();
  }
  return { routes, dynamic };
}

/** The route Rails would pick for a documented METHOD + path (first match in declaration order, globs excluded). */
export function resolveRoute(table: RouteTable, method: string, path: string): Route | undefined {
  const want = path.split('/').filter(Boolean);
  return table.routes.find((r) => {
    if (r.glob || r.verb !== method.toUpperCase()) return false;
    const segs = r.path.split('/').filter(Boolean);
    if (segs.length !== want.length) return false;
    return segs.every((s, i) => {
      const w = want[i]!;
      if (s.startsWith(':')) return true;
      // A documented placeholder (:ref) only matches a route placeholder.
      if (w.startsWith(':')) return false;
      return s === w;
    });
  });
}

export const controllerFile = (controller: string) => `app/controllers/${controller}_controller.rb`;

// ---- Controller actions: request params and response keys ---------------------------------------------------------

export type ParamType = 'integer' | 'number' | 'string' | 'boolean' | 'array' | 'object';

export interface CodeParam {
  /** Dotted path for nested keys (data.user_traits). */
  name: string;
  required: boolean;
  type?: ParamType;
  line: number;
  via?: string;
}

export interface ActionFacts {
  file: string;
  action: string;
  line: number;
  params: CodeParam[];
  /** False when the action also reads params it hands on whole or builds at run time (then removals are unknown). */
  paramsComplete: boolean;
  /** Top-level keys of the JSON the action renders on success. */
  responseKeys: { name: string; line: number }[];
  /** True when every success render is a literal hash (the key set is the whole response). */
  responseComplete: boolean;
  /** Why something could not be determined statically. */
  review: string[];
}

/** Param keys a framework filter sets on the server (not request fields): `params['x'] = <not params['x']>`. */
export function serverSetParams(src: string): Set<string> {
  const out = new Set<string>();
  for (const l of lexRuby(src)) {
    const m = l.code.match(/\bparams\[\s*['":](\w+)['"]?\s*\]\s*=(?!=)\s*(.*)$/);
    if (!m) continue;
    const key = m[1]!;
    const rhs = m[2]!;
    if (!new RegExp(`params\\[\\s*['":]${key}['"]?\\s*\\]`).test(rhs) && !/^if\b/.test(rhs)) out.add(key);
  }
  return out;
}

const RESERVED = new Set(['controller', 'action', 'format', 'id_token_hint']);
const LIT = `['":](\\w[\\w-]*)['"]?`;

function typeAfter(rest: string): ParamType | undefined {
  if (/^\s*\.to_i\b|^\s*\.to_int\b/.test(rest)) return 'integer';
  if (/^\s*\.to_f\b|^\s*\.to_d\b/.test(rest)) return 'number';
  if (/^\s*\.to_s\b/.test(rest)) return 'string';
  if (/^\s*\.to_a\b|^\s*\.each\b|^\s*\.map\b/.test(rest)) return 'array';
  return undefined;
}

interface ParamHelper {
  required: boolean;
  type?: ParamType;
}

/** Methods `def name(arg)` whose body reads `params[arg]` / `params.require(arg)` / `params.fetch(arg)`. */
export function paramHelpers(methods: RubyMethod[]): Map<string, ParamHelper> {
  const out = new Map<string, ParamHelper>();
  for (const m of methods) {
    const arg = m.args
      .split(',')[0]
      ?.trim()
      .replace(/[=:].*$/, '');
    if (!arg) continue;
    const body = m.lines.map((l) => l.code).join('\n');
    const re = new RegExp(
      `params(\\.require\\(\\s*${arg}\\s*\\)|\\.fetch\\(\\s*${arg}\\s*\\)|\\[\\s*${arg}\\s*\\])`,
    );
    if (!re.test(body)) continue;
    const required =
      /\.require\(|\.fetch\(\s*\w+\s*\)|ParameterMissing|blank\?|presence\b.*\|\|\s*raise/.test(body);
    const type: ParamType | undefined = /Array\(|\.to_a\b|is_a\?\(Array\)|split\(/.test(body)
      ? 'array'
      : /\.to_i\b/.test(body)
        ? 'integer'
        : undefined;
    out.set(m.name, { required, ...(type ? { type } : {}) });
  }
  return out;
}

function topLevelKeys(hash: string): string[] {
  // hash: text between the outer braces.
  const keys: string[] = [];
  let depth = 0;
  let seg = '';
  const flush = () => {
    const s = seg.trim();
    seg = '';
    const m =
      s.match(/^['"]([^'"]+)['"]\s*(=>|:)/) ??
      s.match(/^:?([A-Za-z_]\w*[?!]?)\s*=>/) ??
      s.match(/^([A-Za-z_]\w*[?!]?):(?!:)/);
    if (m) keys.push(m[1]!);
  };
  for (let i = 0; i < hash.length; i++) {
    const c = hash[i]!;
    if (c === '{' || c === '[' || c === '(') depth++;
    else if (c === '}' || c === ']' || c === ')') depth--;
    if (c === ',' && depth === 0) {
      flush();
      continue;
    }
    seg += c;
  }
  flush();
  return keys;
}

/** Balanced `{…}` starting at `start` (index of `{`) in `text`; returns the inner text and the end index. */
function balanced(text: string, start: number): { inner: string; end: number } | null {
  let depth = 0;
  for (let i = start; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}') {
      depth--;
      if (depth === 0) return { inner: text.slice(start + 1, i), end: i };
    }
  }
  return null;
}

const ERROR_STATUS = /status:\s*(:(?!ok\b|created\b|accepted\b|no_content\b)\w+|[45]\d\d)/;

/**
 * Read one action: the params it reads (literal keys only), and the top-level keys of the JSON it renders on success.
 * `helpers` = arg-taking param readers (required_param('x')); `readers` = zero-arg methods expanded one level.
 */
export function readAction(
  method: RubyMethod,
  file: string,
  opts: {
    helpers: Map<string, ParamHelper>;
    readers: Map<string, RubyMethod>;
    serverSet: Set<string>;
    /** Every method of the controller and its parents (to name the helper an action delegates to). */
    methods?: RubyMethod[];
  },
): ActionFacts {
  const params = new Map<string, CodeParam>();
  const review: string[] = [];
  let paramsComplete = true;
  const assigned = new Set<string>();
  const add = (p: CodeParam) => {
    if (RESERVED.has(p.name) || opts.serverSet.has(p.name.split('.')[0]!) || assigned.has(p.name)) return;
    const prev = params.get(p.name);
    if (!prev) params.set(p.name, p);
    else {
      prev.required = prev.required || p.required;
      prev.type = prev.type ?? p.type;
    }
  };
  const scan = (lines: RubyLine[], via?: string, expanded = new Set<string>()) => {
    for (const l of lines) {
      const c = l.code;
      // `params = JSON.parse(…)`: a local variable shadows the request params from here on (decoded payloads).
      if (/^\s*params\s*=(?!=)/.test(c)) {
        paramsComplete = false;
        review.push(
          `${file}:${l.n} replaces params with a decoded payload — later reads are not request fields`,
        );
        return;
      }
      const at = (name: string, required: boolean, type?: ParamType) =>
        add({ name, required, line: l.n, ...(type ? { type } : {}), ...(via ? { via } : {}) });
      // Server-side assignments inside the action: params['x'] = request.headers[...] → not a request field.
      for (const m of c.matchAll(new RegExp(`\\bparams\\[\\s*${LIT}\\s*\\]\\s*=(?!=)\\s*(.*)$`, 'g')))
        if (!new RegExp(`params\\[\\s*['":]${m[1]}`).test(m[2]!)) assigned.add(m[1]!);
      // params.require(:x)[.permit(...)]
      for (const m of c.matchAll(
        new RegExp(`\\bparams\\.require\\(\\s*${LIT}\\s*\\)(\\.permit\\(([^)]*)\\))?`, 'g'),
      )) {
        at(m[1]!, true, m[2] ? 'object' : undefined);
        if (m[3] !== undefined)
          for (const k of m[3].matchAll(/:(\w+)|['"](\w+)['"]/g)) at(`${m[1]}.${k[1] ?? k[2]}`, false);
      }
      // params.permit(:a, :b, c: [])
      for (const m of c.matchAll(/\bparams\.permit\(([^)]*)\)/g))
        for (const k of m[1]!.matchAll(/(?:^|[\s,(]):(\w+)|['"](\w+)['"]|(\w+):\s*[[{]/g))
          at(k[1] ?? k[2] ?? k[3]!, false);
      // params.fetch(:x[, default])
      for (const m of c.matchAll(new RegExp(`\\bparams\\.fetch\\(\\s*${LIT}\\s*(,)?`, 'g'))) at(m[1]!, !m[2]);
      // params.dig(:a, :b)
      for (const m of c.matchAll(/\bparams\.dig\(([^)]*)\)/g)) {
        const ks = [...m[1]!.matchAll(/:(\w+)|['"](\w[\w-]*)['"]/g)].map((k) => k[1] ?? k[2]!);
        if (ks.length) at(ks.join('.'), false);
        else review.push(`${file}:${l.n} reads params.dig with computed keys`);
      }
      // params.key?(:x) / has_key? / include? / key? / slice(:a, :b)
      for (const m of c.matchAll(
        new RegExp(`\\bparams\\.(?:key\\?|has_key\\?|include\\?)\\(\\s*${LIT}`, 'g'),
      ))
        at(m[1]!, false);
      for (const m of c.matchAll(/\bparams\.slice\(([^)]*)\)/g))
        for (const k of m[1]!.matchAll(/:(\w+)|['"](\w+)['"]/g)) at(k[1] ?? k[2]!, false);
      // params[:x][:y]… (chains of literal keys)
      for (const m of c.matchAll(/\bparams((?:\[\s*['":]\w[\w-]*['"]?\s*\])+)(.{0,12})/g)) {
        if (/^\s*=(?!=)/.test(m[2]!)) continue;
        const ks = [...m[1]!.matchAll(/\[\s*['":](\w[\w-]*)['"]?\s*\]/g)].map((k) => k[1]!);
        at(ks.join('.'), false, typeAfter(m[2]!));
      }
      // params[variable] → computed key
      for (const m of c.matchAll(/\bparams\[\s*([a-z_@][\w.]*)\s*\]/g))
        if (!/^(true|false|nil)$/.test(m[1]!)) {
          paramsComplete = false;
          review.push(`${file}:${l.n} reads params[${m[1]}] (key computed at run time)`);
        }
      // Bare `params` handed on (to a model, a service, merge, permit!, to_unsafe_h …) → params read there are unknown.
      const bare = c.replace(
        /\bparams\s*(\[|\.(require|permit|fetch|dig|key\?|has_key\?|include\?|slice|present\?|blank\?|inspect)\b)/g,
        '',
      );
      if (/\bparams\b/.test(bare) && !/logger|Rails\.logger|puts\b|Airbrake/.test(c)) {
        paramsComplete = false;
        const prefix = bare.slice(0, bare.search(/\bparams\b/));
        const callee =
          prefix.match(/([A-Za-z_][\w:.]*[?!]?)\s*(?:\(\s*)?(?:[^(),=]+,\s*)*$/)?.[1] ?? 'another method';
        review.push(
          `${file}:${l.n} passes all params to ${callee} — the fields read there are not determined`,
        );
      }
      // required_param('x') style helpers and zero-arg readers.
      for (const [name, h] of opts.helpers)
        for (const m of c.matchAll(new RegExp(`\\b${name}\\s*\\(?\\s*${LIT}`, 'g')))
          at(m[1]!, h.required, h.type);
      for (const [name, r] of opts.readers)
        if (
          !expanded.has(name) &&
          r !== method &&
          new RegExp(`(^|[^\\w.:@])${name}(?![\\w?!:])(?!\\s*=[^=>])`).test(l.skel)
        ) {
          expanded.add(name);
          scan(r.lines.slice(1), name, expanded);
        }
    }
  };
  scan(method.lines.slice(1));
  // Delegation to an argument-taking helper that reads params or the raw body (e.g. proxy_post('/path')).
  const delegates = (opts.methods ?? []).filter(
    (m) =>
      m.args &&
      m !== method &&
      !opts.helpers.has(m.name) &&
      method.lines.slice(1).some((l) => new RegExp(`(^|[^\\w.:@])${m.name}\\s*\\(`).test(l.skel)),
  );
  for (const m of delegates) {
    const body = m.lines.map((l) => l.code).join('\n');
    if (/\bparams\b|\brequest\b/.test(body)) {
      paramsComplete = false;
      review.push(
        `${file}:${method.start} delegates to ${m.name}(…), which reads the request — params not determined`,
      );
    }
  }

  // Responses.
  const text = method.lines.map((l) => l.code).join('\n');
  const lineAt = (idx: number) => method.start + text.slice(0, idx).split('\n').length - 1;
  const responseKeys: ActionFacts['responseKeys'] = [];
  let responseComplete = true;
  let successRenders = 0;
  const seen = new Set<string>();
  for (const m of text.matchAll(/\brender\s*\(?\s*json:\s*/g)) {
    const at = m.index! + m[0].length;
    const after = text.slice(at);
    if (after.startsWith('{')) {
      const b = balanced(text, at);
      if (!b) {
        responseComplete = false;
        continue;
      }
      const tail = text.slice(b.end + 1, b.end + 80).split('\n')[0]!;
      if (ERROR_STATUS.test(tail)) continue;
      successRenders++;
      for (const k of topLevelKeys(b.inner))
        if (!seen.has(k)) {
          seen.add(k);
          responseKeys.push({ name: k, line: lineAt(at) });
        }
    } else {
      const v = after.match(/^([a-z_@][\w@]*)/)?.[1];
      const tail = after.split('\n')[0]!;
      if (ERROR_STATUS.test(tail)) continue;
      successRenders++;
      responseComplete = false;
      if (v) {
        // Keys the action adds to the rendered variable: response['x'] = … (present, but not the whole set).
        for (const a of text.matchAll(
          new RegExp(`\\b${v.replace('@', '\\@')}\\[\\s*['":](\\w+)['"]?\\s*\\]\\s*=(?!=)`, 'g'),
        ))
          if (!seen.has(a[1]!)) {
            seen.add(a[1]!);
            responseKeys.push({ name: a[1]!, line: lineAt(a.index!) });
          }
        review.push(`${file}:${lineAt(at)} renders ${v} — its full key set is built at run time`);
      } else review.push(`${file}:${lineAt(at)} renders a computed value — keys not determined`);
    }
  }
  if (!successRenders) {
    responseComplete = false;
    if (/\brender\s+(plain|html|text|xml|file):|\bredirect_to\b|\bhead\s+:/.test(text))
      review.push(`${file}:${method.start} does not render JSON on success`);
    else if (/\brender_\w+/.test(text) || /\brender\b/.test(text))
      review.push(`${file}:${method.start} renders through a helper — keys not determined`);
    else if (delegates.some((m) => m.lines.some((l) => /\brender\b/.test(l.code))))
      review.push(
        `${file}:${method.start} renders through ${delegates.find((m) => m.lines.some((l) => /\brender\b/.test(l.code)))!.name}(…) — keys not determined`,
      );
    else review.push(`${file}:${method.start} renders a view template or nothing — keys not determined`);
  }
  return {
    file,
    action: method.name,
    line: method.start,
    params: [...params.values()].sort((a, b) => a.name.localeCompare(b.name)),
    paramsComplete,
    responseKeys,
    responseComplete,
    review: [...new Set(review)],
  };
}

/** Parent controller constant of a controller source (`class X < V1::ApiController` → v1/api). */
export function parentController(src: string, ownController: string): string | null {
  const m = src.match(/class\s+[\w:]+\s*<\s*([\w:]+)/);
  if (!m) return null;
  const parent = m[1]!
    .replace(/^::/, '')
    .split('::')
    .map((s) => s.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase())
    .join('/')
    .replace(/_controller$/, '');
  if (parent.includes('/')) return parent;
  // Unqualified constant inside `module V1` → same namespace first.
  const ns = ownController.split('/').slice(0, -1).join('/');
  return ns ? `${ns}/${parent}|${parent}` : parent;
}
